#include <bits/stdc++.h>
using namespace std;
int main(){
    int s;
    int day = 0;
    while (cin >> s) {
        cin.ignore();
        vector<pair<int,int>> iv(s);
        for (int i = 0; i < s; i++) {
            string line; getline(cin, line);
            int h1,m1,h2,m2;
            sscanf(line.c_str(), "%d:%d %d:%d", &h1,&m1,&h2,&m2);
            iv[i] = { h1*60+m1, h2*60+m2 };
        }
        sort(iv.begin(), iv.end());
        vector<pair<int,int>> merged;
        for (auto &p : iv) {
            if (!merged.empty() && p.first <= merged.back().second) merged.back().second = max(merged.back().second, p.second);
            else merged.push_back(p);
        }
        int dayStart = 10*60, dayEnd = 18*60;
        int bestStart = dayStart, bestDur = -1;
        int prevEnd = dayStart;
        for (auto &p : merged) {
            int gap = p.first - prevEnd;
            if (gap > bestDur) { bestDur = gap; bestStart = prevEnd; }
            prevEnd = max(prevEnd, p.second);
        }
        int gap = dayEnd - prevEnd;
        if (gap > bestDur) { bestDur = gap; bestStart = prevEnd; }
        day++;
        int hh = bestStart/60, mm = bestStart%60;
        printf("Day #%d: the longest nap starts at %02d:%02d and will last for ", day, hh, mm);
        if (bestDur < 60) printf("%d minutes.\n", bestDur);
        else printf("%d hours and %d minutes.\n", bestDur/60, bestDur%60);
    }
}

